-- The last ten of the 92 Swiss descriptions. Eight are the listings a second
-- agent confirmed are real (intake/descriptions/checked-doubtful.json),
-- NerdYartist stays listed and says plainly it is an artists' market selling
-- new work (Delfim, 2026-10-08), and Brocante de Rive Nyon is written now its
-- organiser is settled. Same rules and checks as 20261008140000.

begin;

create temporary table new_description (slug text, locale text, value text) on commit drop;

do $$
declare n int;
begin
  update public.texts t set value = d.value, updated_at = now()
    from public.markets m, new_description d
   where t.entity_type = 'market' and t.entity_id = m.id and t.field = 'description'
     and m.slug = d.slug and t.locale = d.locale;
  get diagnostics n = row_count;
  if n <> 40 then raise exception 'expected 40, got %', n; end if;
end $$;

commit;
